type NoteCardProps = {
  content: string;
  date: string;
  selected?: boolean;
  onClick: () => void;
  onEdit: () => void;
  onDelete: () => void;
};

export default function NoteCard({
  content,
  date,
  selected = false,
  onClick,
  onEdit,
  onDelete,
}: NoteCardProps) {
  return (
    <article className="relative">
      <button
        type="button"
        onClick={onClick}
        className={`block h-[202px] w-full cursor-pointer overflow-hidden rounded-[20px] border bg-white p-5 text-left shadow-[0_2px_8px_rgba(0,0,0,0.06)] transition-all ${
          selected
            ? "border-fuchsia-400"
            : "border-transparent hover:-translate-y-0.5 hover:shadow-[0_4px_12px_rgba(0,0,0,0.08)]"
        }`}
      >
        <p className="line-clamp-8 text-[15px] leading-[21px] text-gray-900">
          {content}
        </p>
      </button>
      <p className="mt-2 text-center text-sm leading-5 text-gray-500">{date}</p>
      {selected && (
        <div className="absolute -bottom-12 left-1/2 flex -translate-x-1/2 gap-2">
          <button
            type="button"
            onClick={(event) => {
              event.stopPropagation();
              onEdit();
            }}
            aria-label="Edit note"
            className="flex h-8 w-8 items-center justify-center rounded-full bg-white text-sm shadow-[0_2px_8px_rgba(0,0,0,0.12)] transition-colors hover:bg-gray-100"
          >
            ✎
          </button>
          <button
            type="button"
            onClick={(event) => {
              event.stopPropagation();
              onDelete();
            }}
            aria-label="Delete note"
            className="absolute -bottom-12 left-1/2 flex h-10 w-10 -translate-x-1/2 items-center justify-center rounded-full bg-white shadow-[0_2px_8px_rgba(0,0,0,0.12)] transition-colors hover:bg-gray-100"
          >
            🗑
          </button>
        </div>
      )}
    </article>
  );
}
